			for j := right; j >= left; j-- {
				res[bottom][j] = num
				num++
			}
			bottom--
		}
		if left <= right {
			for i := bottom; i >= top; i-- {
				res[i][left] = num
				num++
			}
			left++
		}
	}
	return res
}

