func minSubArrayLen(target int, nums []int) int {
	left, total := 0, 0
	best := len(nums) + 1
	for right := 0; right < len(nums); right++ {
		total += nums[right]
		for total >= target {
			if right-left+1 < best {
				best = right - left + 1
			}
			total -= nums[left]
			left++
		}
	}
	if best > len(nums) {
		return 0
	}
	return best
}

