func sortByBits(arr []int) []int {
	ones := func(v int) int {
		c := 0
		for v != 0 {
			v &= v - 1
			c++
		}
		return c
	}
	sort.Slice(arr, func(i, j int) bool {
		ci, cj := ones(arr[i]), ones(arr[j])
		if ci != cj {
			return ci < cj
		}
		return arr[i] < arr[j]
	})
	return arr
}

