func reorderList(head *ListNode) {
	if head == nil {
		return
	}
	slow, fast := head, head
	for fast.Next != nil && fast.Next.Next != nil {
		slow = slow.Next
		fast = fast.Next.Next
	}
	mid := slow.Next
	slow.Next = nil
	var prev *ListNode
	for mid != nil {
		nxt := mid.Next
		mid.Next = prev
		prev = mid
		mid = nxt
	}
	first, second := head, prev
	for second != nil {
		nxtFirst, nxtSecond := first.Next, second.Next
		first.Next = second
		second.Next = nxtFirst
		first, second = nxtFirst, nxtSecond
	}
}

