	}
	cur := l.dummy
	for i := 0; i < index; i++ {
		cur = cur.Next
	}
	cur.Next = &ListNode{Val: val, Next: cur.Next}
	l.size++
}

func (l *MyLinkedList) DeleteAtIndex(index int) {
	if index < 0 || index >= l.size {
		return
	}
	cur := l.dummy
	for i := 0; i < index; i++ {
		cur = cur.Next
	}
	cur.Next = cur.Next.Next
	l.size--
}

